tokens = {"color": {"status": {"running": "#1f9d55", "waiting": "#d97706",
                               "offline": "#6b7280", "alert": "#dc2626"}},
          "space": {"1": "4px", "2": "8px"}}
def flat(o, p=()):
    for k, v in o.items():
        yield from flat(v, p + (k,)) if isinstance(v, dict) else [("-".join(p + (k,)), v)]
print(":root {\n" + "\n".join(f"  --{k}: {v};" for k, v in flat(tokens)) + "\n}")
